#!/usr/bin/env python3
import json
import time
import websocket
import urllib.request

# Create a new tab for chrome://settings/cookies
resp = urllib.request.urlopen("http://localhost:1337/json/new?chrome://settings/cookies").read()
tab = json.loads(resp)
ws_url = tab["webSocketDebuggerUrl"]
print("New tab:", tab["id"], tab["url"])

ws = websocket.create_connection(ws_url)
msg_id = 0

def send(method, params=None):
    global msg_id
    msg_id += 1
    ws.send(json.dumps({"id": msg_id, "method": method, "params": params or {}}))
    while True:
        msg = json.loads(ws.recv())
        if msg.get("id") == msg_id:
            return msg

# Wait for page to load
send("Page.enable")
time.sleep(2)

# JavaScript to find and toggle the Do Not Track setting in shadow DOM
js = r"""
(async () => {
  function deepQuery(root, selector) {
    const found = root.querySelector(selector);
    if (found) return found;
    const all = root.querySelectorAll('*');
    for (const el of all) {
      if (el.shadowRoot) {
        const r = deepQuery(el.shadowRoot, selector);
        if (r) return r;
      }
    }
    return null;
  }
  // Wait for settings UI to be ready
  for (let i = 0; i < 30; i++) {
    const toggle = deepQuery(document, '#doNotTrack');
    if (toggle) {
      const checked = toggle.checked;
      if (!checked) {
        toggle.click();
      }
      // Wait for confirmation dialog
      await new Promise(r => setTimeout(r, 500));
      // Confirm if a dialog appears
      const confirmBtn = deepQuery(document, 'settings-do-not-track-confirmation-dialog')
        || deepQuery(document, '.action-button');
      if (confirmBtn) {
        const btn = deepQuery(document, '.action-button');
        if (btn) btn.click();
      }
      await new Promise(r => setTimeout(r, 500));
      const after = deepQuery(document, '#doNotTrack');
      return {found:true, before:checked, after: after ? after.checked : null};
    }
    await new Promise(r => setTimeout(r, 500));
  }
  return {found:false};
})()
"""

result = send("Runtime.evaluate", {"expression": js, "awaitPromise": True, "returnByValue": True})
print("Result:", json.dumps(result.get("result", {}), indent=2))
ws.close()

