#!/usr/bin/env python3
import json
import time
import websocket
import urllib.request

# Get existing page tab
resp = urllib.request.urlopen("http://localhost:1337/json/list").read()
tabs = json.loads(resp)
page = next(t for t in tabs if t["type"] == "page")
ws_url = page["webSocketDebuggerUrl"]
print("Using tab:", page["id"], page["url"])

ws = websocket.create_connection(ws_url)
msg_id = 0

def send(method, params=None, timeout=10):
    global msg_id
    msg_id += 1
    cur = msg_id
    ws.send(json.dumps({"id": cur, "method": method, "params": params or {}}))
    end = time.time() + timeout
    while time.time() < end:
        ws.settimeout(end - time.time())
        try:
            msg = json.loads(ws.recv())
        except Exception:
            continue
        if msg.get("id") == cur:
            return msg
    return None

send("Page.enable")
print("Navigating to chrome://settings/cookies...")
send("Page.navigate", {"url": "chrome://settings/cookies"})
time.sleep(4)

js = r"""
(async () => {
  function deepQuery(root, selector) {
    if (!root) return null;
    try {
      const found = root.querySelector(selector);
      if (found) return found;
    } catch(e){}
    const all = root.querySelectorAll ? root.querySelectorAll('*') : [];
    for (const el of all) {
      if (el.shadowRoot) {
        const r = deepQuery(el.shadowRoot, selector);
        if (r) return r;
      }
    }
    return null;
  }
  function deepQueryAll(root, selector) {
    const out = [];
    if (!root) return out;
    try {
      out.push(...root.querySelectorAll(selector));
    } catch(e){}
    const all = root.querySelectorAll ? root.querySelectorAll('*') : [];
    for (const el of all) {
      if (el.shadowRoot) {
        out.push(...deepQueryAll(el.shadowRoot, selector));
      }
    }
    return out;
  }

  for (let i = 0; i < 40; i++) {
    const toggle = deepQuery(document, '#doNotTrack');
    if (toggle) {
      const before = toggle.checked;
      if (!before) {
        toggle.click();
        await new Promise(r => setTimeout(r, 800));
        // confirm dialog if present
        const dlg = deepQuery(document, 'settings-do-not-track-confirmation-dialog');
        if (dlg) {
          const confirmBtn = deepQuery(dlg.shadowRoot || dlg, '.action-button');
          if (confirmBtn) confirmBtn.click();
        } else {
          const btn = deepQuery(document, '.action-button');
          if (btn && btn.offsetParent !== null) btn.click();
        }
        await new Promise(r => setTimeout(r, 800));
      }
      const after = deepQuery(document, '#doNotTrack');
      return {found:true, before, after: after ? after.checked : null};
    }
    await new Promise(r => setTimeout(r, 500));
  }
  // Diagnostic info
  const ids = deepQueryAll(document, '[id]').slice(0, 30).map(e => e.id);
  return {found:false, ids};
})()
"""

result = send("Runtime.evaluate", {"expression": js, "awaitPromise": True, "returnByValue": True}, timeout=30)
print("Result:", json.dumps(result, indent=2)[:2000])
ws.close()

